begin
wwv_flow_imp_shared.create_list_template(
 p_id=>wwv_flow_imp.id(279674441656835447)
,p_list_template_before_rows=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<div class="amc-TMegaMenu #COMPONENT_CSS_CLASSES#" id="#LIST_ID#">',
'<ul class="amc-TMegaMenu-bar">'))
,p_list_template_after_rows=>wwv_flow_string.join(wwv_flow_t_varchar2(
'</ul>',
'</div>'))
,p_list_template_current=>'<li class="amc-TMegaMenu-item is-current"><a class="amc-TMegaMenu-link" href="#LINK#" aria-current="page"><span class="amc-TMegaMenu-icon fa #ICON_CSS_CLASSES#" aria-hidden="true"></span><span class="amc-TMegaMenu-label">#TEXT#</span></a></li>'
,p_item_templ_curr_w_child=>'<li class="amc-TMegaMenu-item amc-TMegaMenu-item--mega is-current"><button type="button" class="amc-TMegaMenu-link amc-TMegaMenu-trigger" aria-controls="amc-megamenu-#LIST_ITEM_ID#"><span class="amc-TMegaMenu-icon fa #ICON_CSS_CLASSES#" aria-hidden="true"></span><span class="amc-TMegaMenu-label">#TEXT#</span><span class="amc-TMegaMenu-chevron" aria-hidden="true"></span></button><div class="amc-TMegaMenu-panel" id="amc-megamenu-#LIST_ITEM_ID#"><div class="amc-TMegaMenu-panelInner"><a class="amc-TMegaMenu-feature" href="#LINK#"><span class="amc-TMegaMenu-featureIcon fa #ICON_CSS_CLASSES#" aria-hidden="true"></span><span class="amc-TMegaMenu-featureTitle">#TEXT#</span><span class="amc-TMegaMenu-featureDesc">#A01#</span><span class="amc-TMegaMenu-featureGo" aria-hidden="true"></span></a>'
,p_list_template_noncurrent=>'<li class="amc-TMegaMenu-item"><a class="amc-TMegaMenu-link" href="#LINK#"><span class="amc-TMegaMenu-icon fa #ICON_CSS_CLASSES#" aria-hidden="true"></span><span class="amc-TMegaMenu-label">#TEXT#</span></a></li>'
,p_item_templ_noncurr_w_child=>'<li class="amc-TMegaMenu-item amc-TMegaMenu-item--mega"><button type="button" class="amc-TMegaMenu-link amc-TMegaMenu-trigger" aria-controls="amc-megamenu-#LIST_ITEM_ID#"><span class="amc-TMegaMenu-icon fa #ICON_CSS_CLASSES#" aria-hidden="true"></span><span class="amc-TMegaMenu-label">#TEXT#</span><span class="amc-TMegaMenu-chevron" aria-hidden="true"></span></button><div class="amc-TMegaMenu-panel" id="amc-megamenu-#LIST_ITEM_ID#"><div class="amc-TMegaMenu-panelInner"><a class="amc-TMegaMenu-feature" href="#LINK#"><span class="amc-TMegaMenu-featureIcon fa #ICON_CSS_CLASSES#" aria-hidden="true"></span><span class="amc-TMegaMenu-featureTitle">#TEXT#</span><span class="amc-TMegaMenu-featureDesc">#A01#</span><span class="amc-TMegaMenu-featureGo" aria-hidden="true"></span></a>'
,p_before_sub_list=>'<ul class="amc-TMegaMenu-grid">'
,p_after_sub_list=>wwv_flow_string.join(wwv_flow_t_varchar2(
'</ul>',
'</div>',
'</div>',
'</li>'))
,p_sub_list_item_current=>'<li class="amc-TMegaMenu-cell"><a class="amc-TMegaMenu-card" href="#LINK#" aria-current="page"><span class="amc-TMegaMenu-cardIcon fa #ICON_CSS_CLASSES#" aria-hidden="true"></span><span class="amc-TMegaMenu-cardText"><span class="amc-TMegaMenu-cardTitle">#TEXT#</span><span class="amc-TMegaMenu-cardDesc">#A01#</span></span></a></li>'
,p_sub_list_item_noncurrent=>'<li class="amc-TMegaMenu-cell"><a class="amc-TMegaMenu-card" href="#LINK#"><span class="amc-TMegaMenu-cardIcon fa #ICON_CSS_CLASSES#" aria-hidden="true"></span><span class="amc-TMegaMenu-cardText"><span class="amc-TMegaMenu-cardTitle">#TEXT#</span><span class="amc-TMegaMenu-cardDesc">#A01#</span></span></a></li>'
,p_list_template_name=>'AMC Mega Menu'
,p_internal_name=>'AMC_TPL_MEGA_MENU'
,p_javascript_file_urls=>'#APP_FILES#amc-templates/amc-tpl-mega-menu.js'
,p_theme_id=>42
,p_css_file_urls=>'#APP_FILES#amc-templates/amc-tpl-mega-menu.css'
,p_a01_label=>'Description'
,p_list_template_comment=>'List template for top navigation with one level of sub lists. Entries without children are links; entries with children render a menu button that opens a glass panel spanning the bar. The panel shows a feature card linking to the parent entry''s own target, with its icon and Attribute 1 as description, plus a grid of the child entries with their icons and Attribute 1 descriptions. The current entry gets aria-current=page and parents on the current path are highlighted. With JavaScript the button carries aria-expanded and opens on click, Enter or Space, or mouse hover; ArrowDown moves into the panel, ArrowUp and ArrowDown move between its links, ArrowLeft and ArrowRight move along the bar, Escape closes the panel and returns focus, and a click outside closes it. Without JavaScript the panel opens on hover and keyboard focus. The bar scrolls horizontally in narrow containers and the panel stacks in one column below 560px. Template options: Solid panel drops the backdrop blur; Compact bar; Hide feature card; Three columns; Full width bar. Under prefers-reduced-motion the panel appears without the hinge animation.'
);
end;
